import{_ as o,C as i,o as e,c as s,a2 as t,b as n,w as r,a as h,E as d,a3 as u}from"./chunks/framework.CZGNF-7T.js";const g="/assets/layout.TiloWLJ8.png",_=JSON.parse('{"title":"IBS 워크스페이스 시작하기","description":"","frontmatter":{},"headers":[],"relativePath":"intro/getting-started.md","filePath":"intro/getting-started.md","lastUpdated":1788524367000}'),c={name:"intro/getting-started.md"};function E(m,a,f,b,B,p){const l=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="ibs-워크스페이스-시작하기" tabindex="-1">IBS 워크스페이스 시작하기 <a class="header-anchor" href="#ibs-워크스페이스-시작하기" aria-label="Permalink to &quot;IBS 워크스페이스 시작하기&quot;">​</a></h1><blockquote><p>**IBS (Intelligent Business System)**는 부동산 개발사업의 전 과정을 &#39;업무 (Issue)&#39;와 &#39;데이터 파이프라인&#39; 중심으로 관리하고 협업하는 디벨로퍼 전용 업무 플랫폼입니다.</p><p>이 문서는 신규 사용자가 시스템에 접속하여 계정을 설정하고, 팀 워크스페이스에 참여하여 첫 업무를 시작하는 온보딩 과정을 안내합니다.</p></blockquote><h2 id="대상-사용자" tabindex="-1">대상 사용자 <a class="header-anchor" href="#대상-사용자" aria-label="Permalink to &quot;대상 사용자&quot;">​</a></h2><ul><li><strong>개발/사업관리 실무자</strong> - 부지 매입, 인허가, 공정 및 외주 협력사 관리</li><li><strong>분양/영업 담당자</strong> - 동호수 배치, 분양 계약 등록, 권리의무 승계 및 해약 관리</li><li><strong>수납/재무 담당자</strong> - 회차별 대금 수납, 연체료 계산, 자금 출납 및 사업 수지 분석</li><li><strong>임원 및 의사결정자</strong> - 전자결재 승인, 실시간 대시보드 및 지표 모니터링</li></ul><h2 id="시스템-접속-및-온보딩-3단계" tabindex="-1">시스템 접속 및 온보딩 3단계 <a class="header-anchor" href="#시스템-접속-및-온보딩-3단계" aria-label="Permalink to &quot;시스템 접속 및 온보딩 3단계&quot;">​</a></h2><p>IBS를 정상적으로 이용하기 위해서는 계정 생성 후 관리자의 <strong>인사 정보 및 워크스페이스 권한 부여</strong>가 필요합니다.</p>',6)),(e(),n(u,null,{default:r(()=>[d(l,{id:"mermaid-42",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%221.%20%EA%B3%84%EC%A0%95%20%EC%83%9D%EC%84%B1%3Cbr%3Edyibs-staff%20%EA%B0%80%EC%9E%85%22%5D%20--%3E%20B%5B%222.%20%EC%9D%B8%EC%82%AC%2F%EB%B3%B4%EC%A7%81%20%EB%B0%9C%EB%A0%B9%3Cbr%3E%EB%B6%80%EC%84%9C%C2%B7%EC%A7%81%EC%B1%85%20%EB%A7%A4%ED%95%91%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%223.%20%EC%9B%8C%ED%81%AC%EC%8A%A4%ED%8E%98%EC%9D%B4%EC%8A%A4%20%EC%B0%B8%EC%97%AC%3Cbr%3E%EC%97%AD%ED%95%A0%2F%EA%B6%8C%ED%95%9C%20%EB%B6%80%EC%97%AC%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22%F0%9F%9A%80%20%EC%A0%84%EC%B2%B4%20%EA%B8%B0%EB%8A%A5%20%ED%99%9C%EC%84%B1%ED%99%94%3Cbr%3E%EC%A0%84%EC%9E%90%EA%B2%B0%EC%9E%AC%C2%B7%ED%94%84%EB%A1%9C%EC%A0%9D%ED%8A%B8%20%EB%A9%94%EB%89%B4%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h3 id="_1단계-계정-생성-회원-가입" tabindex="-1">1단계: 계정 생성 (회원 가입) <a class="header-anchor" href="#_1단계-계정-생성-회원-가입" aria-label="Permalink to &quot;1단계: 계정 생성 (회원 가입)&quot;">​</a></h3><ul><li><strong>접속 주소</strong>: <a href="https://ibs.dyibs.com" target="_blank" rel="noreferrer">https://ibs.dyibs.com</a></li><li>메인 화면의 <strong>[회원가입]</strong> 링크를 클릭하여 아이디와 비밀번호를 등록합니다.</li><li>가입 시 사내 보안 코드인 **계정 생성코드 (<code>dyibs-staff</code>)**를 반드시 입력해야 합니다.</li></ul><h3 id="_2단계-인사-정보-등록-및-보직-발령-관리자" tabindex="-1">2단계: 인사 정보 등록 및 보직 발령 (관리자) <a class="header-anchor" href="#_2단계-인사-정보-등록-및-보직-발령-관리자" aria-label="Permalink to &quot;2단계: 인사 정보 등록 및 보직 발령 (관리자)&quot;">​</a></h3><ul><li>시스템 관리자가 **[인사 관리]**에서 사용자 계정과 실제 직원 정보 (<code>Staff</code>)를 연결합니다.</li><li>소속 부서와 직책 (<code>StaffAssignment</code>)을 지정받으면 <strong><a href="/approval/">전자결재 시스템</a>의 기안 양식 로드 및 자동 결재선 산출</strong>이 활성화됩니다.</li></ul><h3 id="_3단계-워크스페이스-초대-및-권한-부여-관리자" tabindex="-1">3단계: 워크스페이스 초대 및 권한 부여 (관리자) <a class="header-anchor" href="#_3단계-워크스페이스-초대-및-권한-부여-관리자" aria-label="Permalink to &quot;3단계: 워크스페이스 초대 및 권한 부여 (관리자)&quot;">​</a></h3><ul><li>참여할 워크스페이스 (본사 관리, 프로젝트 등)에 구성원 (<code>Member</code>)으로 초대되고 역할 (<code>Role</code>)을 부여받습니다.</li><li>권한 승인이 완료되면 사이드바에서 담당 프로젝트의 모든 실무 메뉴가 활성화됩니다.</li></ul><h2 id="기본-화면-구성-ui-overview" tabindex="-1">기본 화면 구성 (UI Overview) <a class="header-anchor" href="#기본-화면-구성-ui-overview" aria-label="Permalink to &quot;기본 화면 구성 (UI Overview)&quot;">​</a></h2><p>로그인 후 마주치는 화면은 크게 3개의 핵심 영역으로 구성되어 있습니다.</p><p><img src="'+g+'" alt="레이아웃"></p><ol><li><strong>상단 헤더 바 (Header Bar)</strong>: <ul><li><strong>회사/프로젝트 선택기</strong>: 작업 대상 회사 및 프로젝트를 원클릭으로 전환</li><li><strong>알림 (Notice)</strong>: 나에게 할당된 이슈 변경, 결재 요청, 공지사항 알림</li><li><strong>테마 및 사용자 메뉴</strong>: 라이트/다크 테마 전환 및 내 정보 수정</li></ul></li><li><strong>좌측 사이드바 (Navigation Drawer)</strong>: <ul><li><strong>워크스페이스</strong>: 업무 (Issue), 회의록, 로드맵, 캘린더, 문서, 게시판</li><li><strong>전자결재</strong>: 기안 작성 (17종), 결재 대기/진행함, 완료/공람 문서함</li><li><strong>프로젝트 관리</strong>: 부지 관리, 유닛 설정, 계약 관리, 대금 수납, 회계 자금, 소송 관리</li></ul></li><li><strong>메인 작업 뷰 (Main View)</strong>: <ul><li>개인 맞춤형 위젯 기반의 <a href="/intro/dashboard.html">대시보드</a> 및 선택한 메뉴의 상세 업무 화면이 표시됩니다.</li></ul></li></ol><h2 id="신규-프로젝트-초기-데이터-구축-5단계" tabindex="-1">신규 프로젝트 초기 데이터 구축 5단계 <a class="header-anchor" href="#신규-프로젝트-초기-데이터-구축-5단계" aria-label="Permalink to &quot;신규 프로젝트 초기 데이터 구축 5단계&quot;">​</a></h2><p>새로운 사업지나 워크스페이스를 구축할 때는 다음 순서로 데이터를 설정하는 것을 권장합니다.</p><h3 id="_1단계-프로젝트-기본-정보-등록" tabindex="-1">1단계: <a href="/project/">프로젝트 기본 정보 등록</a> <a class="header-anchor" href="#_1단계-프로젝트-기본-정보-등록" aria-label="Permalink to &quot;1단계: [프로젝트 기본 정보 등록](/project/)&quot;">​</a></h3><ul><li>사업명, 사업 형태 (일반분양, 조합 등), 위치, 사업 기간 등 프로젝트 마스터 정보를 설정합니다.</li></ul><h3 id="_2단계-상품-및-유닛-구성" tabindex="-1">2단계: <a href="/project/units.html">상품 및 유닛 구성</a> <a class="header-anchor" href="#_2단계-상품-및-유닛-구성" aria-label="Permalink to &quot;2단계: [상품 및 유닛 구성](/project/units)&quot;">​</a></h3><ul><li>분양 대상 동·호수 배치와 타입별 전용/공급 면적, 층별 분양가를 등록합니다.</li></ul><h3 id="_3단계-분양-조건-및-예산-편성" tabindex="-1">3단계: <a href="/project/settings.html">분양 조건 및 예산 편성</a> <a class="header-anchor" href="#_3단계-분양-조건-및-예산-편성" aria-label="Permalink to &quot;3단계: [분양 조건 및 예산 편성](/project/settings)&quot;">​</a></h3><ul><li>계약 회차별 납부 비율 (계약금, 중도금, 잔금)과 연체/할인 이율을 설정하고, <a href="/project/budgets.html">사업 예산 항목</a>을 구성합니다.</li></ul><h3 id="_4단계-부지-관리-및-기존-계약-이관" tabindex="-1">4단계: <a href="/project/site-manage.html">부지 관리 및 기존 계약 이관</a> <a class="header-anchor" href="#_4단계-부지-관리-및-기존-계약-이관" aria-label="Permalink to &quot;4단계: [부지 관리 및 기존 계약 이관](/project/site-manage)&quot;">​</a></h3><ul><li>사업 부지의 필지별 토지 소유 현황 및 매입 계약을 등록하고, 기존 수분양자 계약 및 수납 데이터를 이관 등록합니다.</li></ul><h3 id="_5단계-첫-회의록-작성-및-업무-issue-발행" tabindex="-1">5단계: <a href="/work-manage/meeting.html">첫 회의록 작성 및 업무 (Issue) 발행</a> <a class="header-anchor" href="#_5단계-첫-회의록-작성-및-업무-issue-발행" aria-label="Permalink to &quot;5단계: [첫 회의록 작성 및 업무 (Issue) 발행](/work-manage/meeting)&quot;">​</a></h3><ul><li>킥오프 회의록을 작성하여 결정 사항과 액션 아이템을 도출하고, 담당자를 지정하여 첫 <a href="/work-manage/issue.html">업무 (Issue)</a>를 발행합니다.</li></ul><h2 id="일일-권장-업무-루틴-daily-workflow" tabindex="-1">일일 권장 업무 루틴 (Daily Workflow) <a class="header-anchor" href="#일일-권장-업무-루틴-daily-workflow" aria-label="Permalink to &quot;일일 권장 업무 루틴 (Daily Workflow)&quot;">​</a></h2><ul><li><strong>09:00 (출근 &amp; 대시보드 점검)</strong>: <a href="/intro/dashboard.html">대시보드</a>에서 오늘의 일정 (캘린더), 나에게 할당된 업무, 결재 대기 문서를 확인합니다.</li><li><strong>11:00 (회의 및 협업)</strong>: <a href="/work-manage/meeting.html">회의록</a>을 통해 의제를 공유하고, 결정 사항에 따른 후속 조치 업무를 등록합니다.</li><li><strong>14:00 (실무 데이터 처리 &amp; 결재)</strong>: <a href="/contract/">계약 등록</a>, <a href="/payment/">수납 처리</a>를 수행하고 필요한 지출/품의 건은 <a href="/approval/draft.html">전자결재</a>로 상신합니다.</li><li><strong>18:00 (퇴근 전 진척률 갱신)</strong>: 진행한 업무의 진척률 (<code>Done Ratio</code>)과 작업 로그를 갱신하여 팀원들과 진행 상황을 투명하게 공유합니다.</li></ul><h2 id="도움-요청-및-기술-지원" tabindex="-1">도움 요청 및 기술 지원 <a class="header-anchor" href="#도움-요청-및-기술-지원" aria-label="Permalink to &quot;도움 요청 및 기술 지원&quot;">​</a></h2><p>시스템 사용 중 문의사항이나 오류가 발생하면 아래 채널을 이용해 주세요.</p><ul><li><strong>사내 문의 게시판</strong>: <a href="https://ibs.dyibs.com/#/work/project/ibs/forum/1" target="_blank" rel="noreferrer">IBS 기술지원 게시판</a></li><li><strong>담당 부서</strong>: IT·디지털혁신팀</li><li><strong>문의 요령</strong>: 오류 발생 화면 캡처, URL, 재현 경로를 함께 기재해 주시면 신속한 처리가 가능합니다.</li></ul>',27))])}const A=o(c,[["render",E]]);export{_ as __pageData,A as default};
